const fs = require('fs'), os = require('os'), path = require('path'), zlib = require('zlib'), crypto = require('crypto'), { Worker, isMainThread } = require('worker_threads')
const d = fs.mkdtempSync(path.join(os.tmpdir(), 'x-'))
fs.writeFileSync(path.join(d, 'a.txt'), 'x'.repeat(1000))
fs.mkdirSync(path.join(d, 'sub/deep'), { recursive: true })
fs.renameSync(path.join(d, 'a.txt'), path.join(d, 'sub/b.txt'))
fs.writeFileSync(path.join(d, 'c.txt'), 'abcdef')
fs.truncateSync(path.join(d, 'c.txt'), 3)
const fd = fs.openSync(path.join(d, 'c.txt'), 'r+'); fs.fsyncSync(fd); fs.closeSync(fd)
console.log(zlib.gzipSync('hello').length, crypto.createHash('sha256').update('a').digest('hex').slice(0, 8), crypto.randomBytes(4).length)
console.log(fs.readdirSync(d), fs.statSync(d).isDirectory())
fs.unlinkSync(path.join(d, 'c.txt'))
fs.rmSync(d, { recursive: true, force: true })
setTimeout(() => console.log('timer'), 5)
Promise.resolve().then(() => console.log('micro'))
fs.promises.readFile(__filename).then(b => console.log('read', b.length))
new Worker('console.log("worker")', { eval: true }).on('exit', () => console.log('worker exit'))
require('child_process')
